 D=base.deck(); unit=build(a1,a2,D); V=Draft202012Validator(json.loads(SCHEMA.read_text(encoding='utf-8'))); old={t['id'] for r in a1+a2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict) and t.get('id')}
 if [r['sequence'] for r in unit]!=list(range(55,61)) or [r['id'] for r in unit]!=[f'fr-a2-u10-p{i:02d}' for i in range(1,7)]: raise AssertionError('Unit10 continuity failure')
